for(const id of ['isolation','hueCenter','hueWidth','satMin','satMax','lumaMin','lumaMax','cuberesolution','precision','levelmin','levelmax','vectorzoom','sourceformat','matrix','codebits','lowcut','highcut'])$(id).onchange=e=>{if(id==='cuberesolution'){$('vectordetail').value=[16,32,64,128].indexOf(Number($('cuberesolution').value))+1;syncDetail();}if(id==='isolation')updateIsolationControls();if(e.isTrusted&&id==='isolation'&&$('isolation').value==='skin'){for(const [key,v] of Object.entries({hueCenter:25,hueWidth:20,satMin:.1,satMax:1,lumaMin:0,lumaMax:1}))$(key).value=v;}if(id==='vectorzoom'){syncMagnification();return;}if(streaming)start();};document.querySelectorAll('[data-range]').forEach(b=>b.onclick=()=>{const [min,max]=b.dataset.range.split(',');$('levelmin').value=min;$('levelmax').value=max;if(streaming)start();});
const viewTabs=document.querySelector('.view-tabs');if(!embedded&&!qaLayout.has('visual')&&!qaLayout.has('ogbench')){const tab=document.createElement('button');tab.id='gprimetab';tab.type='button';tab.textContent='GPrime';tab.setAttribute('role','tab');tab.setAttribute('aria-controls','scopeview');tab.setAttribute('aria-selected','false');tab.tabIndex=-1;tab.onclick=()=>selectPage('gprime');$('scopestab').after(tab);bindViewKeys();document.body.classList.add('has-gprime-tab');}
function placeViewTabs(){if(!homeScreenLaunch)$('fullscreencontrols').prepend($('start'));viewTabs.append($('scopestab'));if($('gprimetab'))viewTabs.append($('gprimetab'));viewTabs.append($('settings'));$('fullscreencontrols').before(viewTabs);viewTabs.setAttribute('aria-owns',$('gprimetab')?'scopestab gprimetab settings':'scopestab settings');}

