 instances=createScopeHost({getLayout:()=>layout,getArrangement:()=>[layoutMode,layoutShare],getGlobal:()=>displayStyle,globalControls:fields,getStorageSeed:()=>Object.fromEntries(['scopeDebugV1','scopeQualityV1','scopeTraceStyleV1','scopeWaveColourV1','scopeVectorColourV1','scopeTwinColourV1','scopeTwinOrientationV1','scopePqWaveV1'].map(k=>[k,localStorage.getItem(k)])),changed:()=>{dirty=true;},startAll:start,isRunning:()=>streaming,isDedicated:()=>gprimePage,readRoot:()=>({zoom:scopeZoom,setZoom:setScopeZoom,resetZoom:resetScopeZoom}),assign:(slot,type)=>changeLayout(assignSlot(layout,slot,type)),parking:()=>parking,settingsChanged:()=>viewerSettings?.persist(),wake:()=>{if(streaming)void keepAwake.retry();}});applyLayout(false);$('clearsnapshots').onclick=()=>{if(!globalThis.confirm('Clear all saved scope snapshots on this device?'))return;snapshots.clear();for(const p of instances.panels.values())p.engine?.clearSnapshots?.();void snapshotStore().clearAll();};
